def transform(grid):
    from collections import Counter
    rows, cols = len(grid), len(grid[0])
    output = [list(row) for row in grid]

    # Find separator rows (uniform rows) and columns (uniform columns)
    sep_rows = set(r for r in range(rows) if len(set(grid[r])) == 1)
    sep_cols = set(c for c in range(cols) if len(set([grid[r][c] for r in range(rows)])) == 1)

    # Get background - most common non-separator value
    non_sep = [grid[r][c] for r in range(rows) for c in range(cols)
               if r not in sep_rows and c not in sep_cols]
    bg = Counter(non_sep).most_common(1)[0][0] if non_sep else 0

    # Find contiguous ranges of non-separator rows/cols
    row_intervals = []
    r = 0
    while r < rows:
        if r in sep_rows:
            r += 1
        else:
            start, r = r, r + 1
            while r < rows and r not in sep_rows:
                r += 1
            row_intervals.append((start, r - 1))

    col_intervals = []
    c = 0
    while c < cols:
        if c in sep_cols:
            c += 1
        else:
            start, c = c, c + 1
            while c < cols and c not in sep_cols:
                c += 1
            col_intervals.append((start, c - 1))

    # Process each region
    for r_start, r_end in row_intervals:
        for c_start, c_end in col_intervals:
            vals = []
            for r in range(r_start, r_end + 1):
                for c in range(c_start, c_end + 1):
                    vals.append(grid[r][c])

            reg_size = len(vals)
            if reg_size == 0:
                continue

            counts = Counter(vals)

            # Find most common color in region (often background)
            most_common = counts.most_common(1)[0][0]

            # Find all non-most-common colors (intruders)
            intruders = [k for k in counts.keys() if k != most_common]

            # Threshold logic based on region size and intruder count
            # For size 15: threshold is 3 (fill if >=3)
            # For size 25: threshold is 2 (fill if >=3, based on demos)

            threshold = (reg_size + 4) // 5
            intruder_total = sum(counts[k] for k in intruders)

            if intruder_total >= threshold and intruders:
                # Fill entire region with the most common intruder
                main_intruder = sorted(intruders, key=lambda x: -counts[x])[0]
                for r in range(r_start, r_end + 1):
                    for c in range(c_start, c_end + 1):
                        if r not in sep_rows and c not in sep_cols:
                            output[r][c] = main_intruder
            else:
                # Clean region - replace all non-background with background
                for r in range(r_start, r_end + 1):
                    for c in range(c_start, c_end + 1):
                        if r not in sep_rows and c not in sep_cols:
                            if grid[r][c] != bg:
                                output[r][c] = bg

    return output
